package org.scalamock.util

import scala.scalajs.js

/**
 *  Mocks of Scala.js types are non-native JS classes generated by a macro, so their members
 *  are not exposed to JS by the compiler. Mock functions and the methods dispatching to them
 *  are therefore assigned as JS properties of the mock instance.
 */
private[scalamock] object JsMockRuntime:
  def getMember(obj: Any, name: String): Any =
    obj.asInstanceOf[js.Dynamic].selectDynamic(name)

  def setMember(obj: Any, name: String, value: Any): Unit =
    obj.asInstanceOf[js.Dynamic].updateDynamic(name)(value.asInstanceOf[js.Any])

  /** Default value of each parameter, if it has one. */
  type Defaults = Seq[Option[Any]]

  /** An argument omitted at a call site of a 'js.native' default argument arrives as undefined. */
  private def arg(value: Any, defaults: Defaults, idx: Int): Any =
    if js.isUndefined(value) then defaults(idx).getOrElse(value) else value

  def fn0(f: Function0[Any], defaults: Defaults): Any = js.Any.fromFunction0(() => f())
  def fn1(f: Function1[Any, Any], defaults: Defaults): Any = js.Any.fromFunction1(a1 => f(arg(a1, defaults, 0)))
  def fn2(f: Function2[Any, Any, Any], defaults: Defaults): Any = js.Any.fromFunction2((a1, a2) => f(arg(a1, defaults, 0), arg(a2, defaults, 1)))
